const int MAXN = 300005, LOGN = 20;
struct Edge { int to, w; };
vector<Edge> adj[MAXN];
int parent_dsu[MAXN], jump[MAXN], up[MAXN][LOGN], depth[MAXN], xr[MAXN], tin[MAXN], tout[MAXN], timer, bit[MAXN + 5];
int find_dsu(int x) { return parent_dsu[x] == x ? x : (parent_dsu[x] = find_dsu(parent_dsu[x])); }
int find_jump(int x) { return jump[x] == x ? x : (jump[x] = find_jump(jump[x])); }
void bit_add(int idx, int val) { for (; idx <= timer; idx += idx & -idx) bit[idx] += val; }
int bit_query(int idx) { int s = 0; for (; idx > 0; idx -= idx & -idx) s += bit[idx]; return s; }
int dfs1(int np,int lst) {
    tin[np] = ++timer; up[np][0] = lst; depth[np] = depth[lst] + 1;
    for (int k = 1; k < LOGN; k++) up[np][k] = up[up[np][k - 1]][k - 1];
    for (auto& e : adj[np]) if (e.to != lst) { xr[e.to] = xr[np] ^ e.w; dfs1(e.to, np); }
    tout[np] = timer; return 0;
}
int get_lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u, v);
    for (int k = LOGN - 1; k >= 0; k--) if (depth[u] - (1 << k) >= depth[v]) u = up[u][k];
    if (u == v) return u;
    for (int k = LOGN - 1; k >= 0; k--) if (up[u][k] != up[v][k]) { u = up[u][k]; v = up[v][k]; }
    return up[u][0];
}
struct Query { int u, v, x, is_tree; };
