    }
    for (int i = 1; i <= n; i++) if (!tin[i]) dfs1(i, 0);
    for (int i = 0; i < q; i++) {
        if (queries[i].is_tree) { cout << "YES\n"; continue; }
        int u = queries[i].u, v = queries[i].v, x = queries[i].x, l = get_lca(u, v);
        if ((xr[u] ^ xr[v] ^ x) != 1 || (bit_query(tin[u]) + bit_query(tin[v]) - 2 * bit_query(tin[l])) > 0) {
